/** Returns true while React renders a component. Dev-only diagnostic. */
export declare function isRenderingComponent(): boolean;
/**
 * Returns `fn` wrapped so that, in development, `message` is warned once per process when a
 * component calls it during render. Wrapped functions call each other, so only the outermost
 * call warns.
 */
export declare function withWarnOnceIfCalledDuringRender<Args extends unknown[], Result>(fn: (...args: Args) => Result, message: string): (...args: Args) => Result;
